const QUESTIONS = [
  {
    id: "q1",
    prompt: "Which of the following are statically typed languages?",
    helpText: "Tip: Static typing means variable types are checked at compile time. Select all that apply.",
    options: [
      { value: "java", label: "Java" },
      { value: "python", label: "Python" },
      { value: "rust", label: "Rust" },
      { value: "javascript", label: "JavaScript" },
    ],
  },
  {
    id: "q2",
    prompt: "Which of these languages run primarily in a web browser?",
    options: [
      { value: "javascript", label: "JavaScript" },
      { value: "cpp", label: "C++" },
      { value: "typescript", label: "TypeScript" },
      { value: "wasm", label: "WebAssembly" },
    ],
  },
  {
    id: "q3",
    prompt: "Which languages were created in the 1970s?",
    options: [
      { value: "c", label: "C" },
      { value: "swift", label: "Swift" },
      { value: "sql", label: "SQL" },
      { value: "kotlin", label: "Kotlin" },
    ],
  },
];

function Question({ question, index, value, onChange }) {
  const helpId = question.helpText ? `${question.id}-help` : undefined;

  return (
    <fieldset className="form-field" aria-describedby={helpId}>
      <legend>
        <span className="question-number">Question {index + 1}</span>
        {question.prompt}
      </legend>

      {question.helpText && (
        <p id={helpId} className="help-text">{question.helpText}</p>
      )}

      <div className="options">
        {question.options.map((opt) => {
          const inputId = `${question.id}-${opt.value}`;
          const checked = value.includes(opt.value);
          return (
            <label key={opt.value} className="option" htmlFor={inputId}>
              <input
                id={inputId}
                type="checkbox"
                name={question.id}
                value={opt.value}
                checked={checked}
                onChange={(e) => onChange(question.id, opt.value, e.target.checked)}
              />
              <span className="option-label">{opt.label}</span>
            </label>
          );
        })}
      </div>
    </fieldset>
  );
}

