const { useState, useMemo, useId } = React;

const QUESTIONS = [
  {
    id: "q1",
    prompt: "Which of the following are statically typed languages?",
    helpText: "Tip: Static typing means variable types are checked at compile time. Select all that apply.",
    options: [
      { value: "java", label: "Java" },
      { value: "python", label: "Python" },
      { value: "rust", label: "Rust" },
      { value: "javascript", label: "JavaScript" },
    ],
  },
  {
    id: "q2",
    prompt: "Which of these languages run primarily in a web browser?",
    options: [
      { value: "javascript", label: "JavaScript" },
      { value: "cpp", label: "C++" },
      { value: "typescript", label: "TypeScript" },
      { value: "wasm", label: "WebAssembly" },
    ],
  },
  {
    id: "q3",
    prompt: "Which languages were created in the 1970s?",
    options: [
      { value: "c", label: "C" },
      { value: "swift", label: "Swift" },
      { value: "sql", label: "SQL" },
      { value: "kotlin", label: "Kotlin" },
    ],
  },
];

function Question({ question, index, value, onChange }) {
  const helpId = question.helpText ? `${question.id}-help` : undefined;

  return (
    <fieldset className="form-field" aria-describedby={helpId}>
      <legend>
        <span className="question-number">Question {index + 1}</span>
        {question.prompt}
      </legend>

      {question.helpText && (
        <p id={helpId} className="help-text">{question.helpText}</p>
      )}

      <div className="options">
        {question.options.map((opt) => {
          const inputId = `${question.id}-${opt.value}`;
          const checked = value.includes(opt.value);
          return (
            <label key={opt.value} className="option" htmlFor={inputId}>
              <input
                id={inputId}
                type="checkbox"
                name={question.id}
                value={opt.value}
                checked={checked}
                onChange={(e) => onChange(question.id, opt.value, e.target.checked)}
              />
              <span className="option-label">{opt.label}</span>
            </label>
          );
        })}
      </div>
    </fieldset>
  );
}

function Quiz() {
  const [answers, setAnswers] = useState(() =>
    Object.fromEntries(QUESTIONS.map((q) => [q.id, []]))
  );
  const [submitted, setSubmitted] = useState(null);

  const handleChange = (qid, value, checked) => {
    setAnswers((prev) => {
      const current = prev[qid];
      const next = checked
        ? [...current, value]
        : current.filter((v) => v !== value);
      return { ...prev, [qid]: next };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const summary = QUESTIONS.map((q) => ({
      prompt: q.prompt,
      selected: q.options
        .filter((o) => answers[q.id].includes(o.value))
        .map((o) => o.label),
    }));
    setSubmitted(summary);
  };

  return (
    <section className="quiz-card" aria-labelledby="quiz-title">
      <header className="quiz-header">
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p>Three questions about programming languages. Pick every answer you think is correct.</p>
      </header>

      <form className="quiz-form" onSubmit={handleSubmit} noValidate>
        {QUESTIONS.map((q, i) => (
          <Question
            key={q.id}
            question={q}
            index={i}
            value={answers[q.id]}
            onChange={handleChange}
          />
        ))}

        <div className="actions">
          <button type="submit" className="btn">Submit answers</button>
        </div>
      </form>

      <div aria-live="polite" aria-atomic="true">
        {submitted && (
          <div className="status" role="status">
            <h2>Answers submitted</h2>
            <p>Here's a summary of your selections:</p>
            <ul>
              {submitted.map((item, i) => (
                <li key={i}>
                  <strong>{item.prompt}</strong>{" "}
                  {item.selected.length > 0
                    ? `— ${item.selected.join(", ")}`
                    : "— (no selection)"}
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </section>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<Quiz />);

